    void importFile()throws Exception {RpgBackupActivity a=(RpgBackupActivity)startActivitySync(new Intent(c,RpgBackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();main(()->action(a.getWindow().getDecorView(),a.getString(R.string.ref_import)).performClick());fillPasswordDialog(a,1);clickSystem(args.getString("name"));waitText(a,a.getString(R.string.ref_restored));main(()->{capture(a.getWindow().getDecorView(),"reinstalled-restore-complete.png");a.finish();});reinstalled();}
    void reinstalled()throws Exception {
        account=SubscriptionStore.accountKey(c);JSONObject archive=new JSONObject(read(new File(c.getExternalFilesDir(null),"refinement-reinstall-expected.json")));JSONObject old=archive.getJSONObject("document").getJSONObject("future").getJSONObject("rpg");JSONObject state=RpgProgressStore.export(c,account).getJSONObject("rpg");
        write(new File(c.getExternalFilesDir(null),"refinement-reinstalled-actual.json"),state.toString().getBytes(StandardCharsets.UTF_8));
        check(state.getLong("xp")>=old.getLong("xp"),"Reinstalled Android restores accumulated XP");
        JSONObject restored=state.getJSONObject("achievements"),previous=old.getJSONObject("achievements");check(restored.length()==53&&previous.length()==53,"Both complete original catalogs present");
        for(RpgCatalog.Entry entry:RpgCatalog.ALL){JSONObject a=restored.getJSONObject(entry.id),b=previous.getJSONObject(entry.id);
            for(String field:new String[]{"id","target","progress","progress_days","progress_weeks","progress_ratio","required_days","required_weeks","unlocked","first_earned_at","reward_xp","rule_version"})if(b.has(field))check(a.has(field)&&String.valueOf(a.get(field)).equals(String.valueOf(b.get(field))),"Restored achievement fact "+entry.id+"/"+field);
            if(b.optBoolean("unlocked"))check(a.optString("time_basis").equals("verified_trusted_journal"),"Restored acquisition retains explicit journal provenance");
        }
        check(state.optString("equipped_title").equals(old.optString("equipped_title")),"Reinstalled Android restores equipped title");List<String> saved=new ArrayList<>();JSONArray ids=archive.getJSONObject("showcase").getJSONArray("ids");for(int i=0;i<ids.length();i++)saved.add(ids.getString(i));check(RpgShowcase.selected(c,state).equals(saved),"Reinstalled Android restores ordered three medals");check(SubscriptionStore.load(c,AppPreferences.loadSnapshot(c))!=null,"Reinstalled Android restores registered payment reference");
    }
    View action(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=action(((ViewGroup)v).getChildAt(i),text);if(found!=null)return found;}return null;}
    android.view.accessibility.AccessibilityNodeInfo findNode(android.view.accessibility.AccessibilityNodeInfo node,String text){if(node==null)return null;if(node.getText()!=null&&node.getText().toString().equalsIgnoreCase(text)){while(node!=null&&!node.isClickable())node=node.getParent();return node;}for(int i=0;i<node.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo child=node.getChild(i),found=findNode(child,text);if(found!=null)return found;}return null;}
    int passwordNodes(android.view.accessibility.AccessibilityNodeInfo node){if(node==null)return 0;int count=0;if(node.isEditable()){Bundle b=new Bundle();b.putCharSequence(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"emulator-only-password");check(node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SET_TEXT,b),"Actual password input accepts text");count++;}for(int i=0;i<node.getChildCount();i++)count+=passwordNodes(node.getChild(i));return count;}
    void waitPasswords(int expected)throws Exception {for(int i=0;i<40;i++){Thread.sleep(150);if(passwordNodes(getUiAutomation().getRootInActiveWindow())==expected){waitForIdleSync();return;}}throw new AssertionError("Password dialog inputs not ready");}
    void collectInputs(View view,List<EditText> inputs){if(view instanceof EditText)inputs.add((EditText)view);if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)collectInputs(((ViewGroup)view).getChildAt(i),inputs);}
    void fillPasswordDialog(RpgBackupActivity a,int expected)throws Exception {
        java.lang.reflect.Field field=RpgBackupActivity.class.getDeclaredField("passwordDialog");field.setAccessible(true);
        for(int i=0;i<40;i++){Thread.sleep(150);waitForIdleSync();androidx.appcompat.app.AlertDialog dialog=(androidx.appcompat.app.AlertDialog)field.get(a);if(dialog!=null&&dialog.isShowing()){main(()->{List<EditText> inputs=new ArrayList<>();collectInputs(dialog.getWindow().getDecorView(),inputs);check(inputs.size()==expected,"Actual password dialog has required input fields");for(EditText input:inputs)input.setText("emulator-only-password");check(dialog.getButton(-1).performClick(),"Actual confirmation button invokes its handler");});return;}}throw new AssertionError("Actual password dialog unavailable");
    }
    boolean setDocumentName(android.view.accessibility.AccessibilityNodeInfo n,String name){if(n==null)return false;if(n.isEditable()&&n.getPackageName().toString().contains("documentsui")){Bundle b=new Bundle();b.putCharSequence(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,name);return n.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SET_TEXT,b);}for(int i=0;i<n.getChildCount();i++)if(setDocumentName(n.getChild(i),name))return true;return false;}
    void documentName(String name)throws Exception {for(int i=0;i<40;i++){Thread.sleep(150);if(setDocumentName(getUiAutomation().getRootInActiveWindow(),name))return;}throw new AssertionError("Document filename input unavailable");}
    String nodeDump(android.view.accessibility.AccessibilityNodeInfo n){if(n==null)return "null";StringBuilder s=new StringBuilder(n.toString()).append("\n");for(int i=0;i<n.getChildCount();i++)s.append(nodeDump(n.getChild(i)));return s.toString();}
