    String texts(View v){StringBuilder out=new StringBuilder();if(v instanceof TextView)out.append(((TextView)v).getText()).append('\n');if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.append(texts(((ViewGroup)v).getChildAt(i)));return out.toString();}
    void saf()throws Exception {RpgBackupActivity a=(RpgBackupActivity)startActivitySync(new Intent(c,RpgBackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();main(()->{View button=action(a.getWindow().getDecorView(),a.getString(R.string.ref_export));check(button!=null&&button.isEnabled(),"Backup export action enabled");button.performClick();});Thread.sleep(300);fillPasswordDialog(a,2);String name="GPT-HUD-refinement-"+System.nanoTime()+".gpthud";documentName(name);clickSystem("SAVE","Save","저장");waitText(a,a.getString(R.string.ref_exported));write(new File(c.getExternalFilesDir(null),"refinement-reinstall-expected.json"),RpgProgressStore.archive(c,SubscriptionStore.accountKey(c)).toString().getBytes(StandardCharsets.UTF_8));write(new File(c.getExternalFilesDir(null),"refinement-reinstall-name.txt"),name.getBytes(StandardCharsets.UTF_8));main(()->{capture(a.getWindow().getDecorView(),"saf-export-complete.png");action(a.getWindow().getDecorView(),a.getString(R.string.ref_import)).performClick();});Thread.sleep(300);fillPasswordDialog(a,1);clickSystem(name);waitText(a,a.getString(R.string.ref_restored));main(()->{capture(a.getWindow().getDecorView(),"saf-restore-complete.png");a.finish();});check(true,"Actual DocumentsUI create and open flow completes encrypted restore");}
    void capture(View view,String name){try{check(view.getWidth()>0&&view.getHeight()>0,"Actual laid-out Android window");Bitmap b=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));File folder=new File(c.getExternalFilesDir(null),"refinement-captures");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}catch(Exception e){throw new RuntimeException(e);}}
